def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales y devuelve
    la tupla (elemento, longitud). Si hay empate, devuelve la primera encontrada.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            racha_actual += 1
        else:
            if racha_actual > max_racha:
                max_racha = racha_actual
                max_elemento = lista[i - 1]
            racha_actual = 1

    # Verificar la última racha
    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minúscula y las siguientes con su inicial en mayúscula,
    sin guiones bajos.

    Args:
        s: La cadena de texto a convertir.

    Returns:
        La cadena convertida en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(result) > 0:
                result.append(word[0].upper() + word[1:])
            else:
                result.append(word)
    return ''.join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def mcd(a: int, b: int) -> int:
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones.

    'aaabb' se convierte en 'a3b2'.
    Si la versión comprimida es más corta que la original,
    devuelve la versión comprimida. Si no, devuelve la original.
    """
    if not s:
        return s

    # Contar repeticiones de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la versión comprimida
    compressed = ""
    for char, count in counts.items():
        compressed += char * count

    # Verificar si es más corta
    if len(compressed) < len(s):
        return compressed
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    if not s:
        return True

    open_brackets = {'(', '[', '{'}
    close_brackets = {')', ']', '}'}

    stack = []
    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

